<script lang="ts">
	import geometry from '$lib/visualizations/openhie/instrument.json';
	import { COMPONENTS, type ComponentId, type Snapshot } from '$lib/visualizations/openhie';
	let {
		snapshot,
		selected,
		onselect
	}: { snapshot: Snapshot; selected: ComponentId | null; onselect: (id: ComponentId) => void } =
		$props();
	const position = $derived(geometry.carriage.positions[snapshot.activeComponent]);
</script>

<!-- eslint-disable svelte/no-at-html-tags -- Trusted, committed SVG generated by the vendored Anatomy kit; no reader or URL input is interpolated into the markup. -->

<div class="ohie-instrument">
	<svg
		class="iso ohie-machine"
		viewBox={`0 0 ${geometry.width} ${geometry.height}`}
		role="img"
		aria-label={`A mechanical model of the exchange. ${snapshot.title}. ${snapshot.explanation}`}
	>
		<title>OpenHIE as a controlled exchange instrument</title>
		<desc
			>The identity index, reference mechanism and shared-record archive have separate
			responsibilities. The carriage marks the current exchange event. Highlighting shows the active
			service; it does not mean every request visits every part.</desc
		>
		{#each geometry.parts as part (part.id)}
			{#if !('recordIndex' in part) || snapshot.persistedCount >= Number(part.recordIndex)}
				<g
					class:is-active={part.component === snapshot.activeComponent}
					class:is-inspected={part.component === selected}
					data-component={part.component}>{@html part.svg}</g
				>
			{/if}
		{/each}
		<g class="ohie-carriage" transform={`translate(${position[0]} ${position[1]})`}
			>{@html geometry.carriage.svg}</g
		>
	</svg>
	{#each COMPONENTS as part, i (part.id)}
		{@const marker = geometry.markers[part.id]}
		<button
			type="button"
			class="ohie-part-pin"
			class:current={snapshot.activeComponent === part.id}
			class:inspected={selected === part.id}
			style={`left:${(marker[0] / geometry.width) * 100}%;top:${(marker[1] / geometry.height) * 100}%`}
			aria-label={`Inspect ${part.title}`}
			aria-pressed={selected === part.id}
			onclick={() => onselect(part.id)}>{String(i + 1).padStart(2, '0')}</button
		>
	{/each}
</div>
